def text(key: str, language: str = "ru", **kwargs: object) -> str:
    variants = STRINGS.get(key)
    if variants is None:
        return key
    index = {"ru": 0, "kk": 1, "en": 2}.get(language, 0)
    value = variants[index] or variants[0]
    return value.format(**kwargs) if kwargs else value
